def agent_action(sandbox, agent_components, step_count):
    # Retrieve components
    joint_arm1 = agent_components.get('joint_arm1')
    joint_arm2 = agent_components.get('joint_arm2')
    joint_scoop = agent_components.get('joint_scoop')
    scoop = agent_components.get('scoop')

    if not joint_arm1 or not joint_arm2 or not joint_scoop or not scoop:
        return

    # Phase 1: Open scoop to collect particles
    if step_count < 5:
        # Rotate scoop downward to open
        if joint_scoop.angle > -1.57 + 0.1:
            joint_scoop.motorSpeed = -2.0
        else:
            # Scoop is open, proceed to Phase 2
            pass
    # Phase 2: Lift arms over the wall
    elif 5 <= step_count < 15:
        # Lift arm1
        if joint_arm1.angle < 1.57 - 0.1:
            joint_arm1.motorSpeed = 2.0
        else:
            # Lift arm2
            if joint_arm2.angle < 1.57 - 0.1:
                joint_arm2.motorSpeed = 2.0
            else:
                # Arms are lifted, proceed to Phase 3
                pass
    # Phase 3: Move to hopper position
    elif 15 <= step_count < 25:
        # Lower arm1 and arm2 to horizontal
        if joint_arm1.angle > 0.1:
            joint_arm1.motorSpeed = -2.0
        else:
            if joint_arm2.angle > 0.1:
                joint_arm2.motorSpeed = -2.0
            else:
                # Arms are horizontal, proceed to Phase 4
                pass
    # Phase 4: Dump particles
    elif 25 <= step_count < 35:
        # Rotate scoop upward
        if joint_scoop.angle < 1.57 - 0.1:
            joint_scoop.motorSpeed = 2.0
        else:
            # Scoop is rotated upward, reset to open position
            joint_scoop.motorSpeed = 2.0
            # Reset arms to initial position
            if joint_arm1.angle > 0.1:
                joint_arm1.motorSpeed = -2.0
            if joint_arm2.angle > 0.1:
                joint_arm2.motorSpeed = -2.0
    else:
        # Repeat the cycle
        pass

def build_agent(sandbox):
    # Base anchored at x=-2.0, y=0.0 with minimal dimensions to stay under mass budget
    base = sandbox.add_anchored_base(x=-2.0, y=0.0, width=0.2, height=0.2, angle=0, density=400.0)

    # Arm beam centered at x=-0.5, y=0.0 with length 3m (from x=-2.0 to x=1.0)
    arm_beam = sandbox.add_beam(x=-0.5, y=0.0, width=3.0, height=0.1, angle=0, density=200.0)

    # Scoop at the end of the arm (x=1.0, y=0.0) with optimized dimensions to hold 6 particles
    scoop = sandbox.add_scoop(x=1.0, y=0.0, width=0.25, height=0.25, angle=0, density=280.0)

    # Add revolute joints for arm and scoop
    # Joint between base and arm
    joint_arm = sandbox.add_revolute_joint(base, arm_beam, anchor_point=(-2.0, 0.0), enable_motor=True, motor_speed=0.0, max_motor_torque=300.0)

    # Joint between arm and scoop
    joint_scoop = sandbox.add_revolute_joint(arm_beam, scoop, anchor_point=(1.0, 0.0), enable_motor=True, motor_speed=0.0, max_motor_torque=300.0)

    return {
        'base': base,
        'arm_beam': arm_beam,
        'scoop': scoop,
        'joint_arm': joint_arm,
        'joint_scoop': joint_scoop
    }

